var n=`0413-irish-stew`;var i=`world-0413`;var a=`IE`;var r=`northern-europe`;var o=4;var s=111;var l={en:`Irish Stew`,ua:`Ірландське рагу`};var g={en:`A traditional dish from Ireland, centered on lamb, yellow onion, potato, carrot. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірландія. Основні складники: ягнятина, жовта цибуля, картопля, морква. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`lamb`,800,`g`],[`yellow-onion`,180,`g`],[`unsalted-butter`,40,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 95 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 95 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:95,i:[[`water`,1100,`ml`],[`potato`,850,`g`],[`carrot`,300,`g`],[`thyme`,4,`sprig`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,15,`g`]]}];var u={slug:n,id:i,country:`IE`,region:r,servings:4,minutes:111,title:l,text:g,steps:d};export{a as country,u as default,i as id,s as minutes,r as region,o as servings,n as slug,d as steps,g as text,l as title};